<script setup lang="ts">
/**
 * RichTextContent.Item: a list’s item and its drawn blocks.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rich-text-content.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { inject } from 'vue'

import { richTextPositionAttrs, type RichTextDrawnBlock } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/rich-text-content.module.css'
import CodeBlock from './CodeBlock.vue'
import Heading from './Heading.vue'
import RichTextContentBlocks from './RichTextContentBlocks.vue'
import RichTextContentInlines from './RichTextContentInlines.vue'
import Text from './Text.vue'

export interface RichTextContentItemProps {
  blocks: RichTextDrawnBlock[]
}

defineOptions({ name: 'RichTextContentItem', inheritAttrs: false })

defineProps<RichTextContentItemProps>()
const owner = inject<Record<string, any>>('polymorph:RichTextContent', {})
</script>

<template>
  <li :class="styles.item">
    <template v-for="(block, index) in blocks" :key="index">
      <Text v-if="block.kind === 'paragraph'" :size="owner.size">
        <RichTextContentInlines :inlines="block.inlines" />
      </Text>
      <Heading v-else-if="block.kind === 'heading'" :level="block.level">
        {{ block.text }}
      </Heading>
      <h4
        v-else-if="block.kind === 'ownHeading' && block.level === 4"
        :class="styles.heading"
        :data-level="String(block.level)"
      >
        <RichTextContentInlines :inlines="block.inlines" />
      </h4>
      <h3
        v-else-if="block.kind === 'ownHeading' && block.level === 3"
        :class="styles.heading"
        :data-level="String(block.level)"
      >
        <RichTextContentInlines :inlines="block.inlines" />
      </h3>
      <h2
        v-else-if="block.kind === 'ownHeading'"
        :class="styles.heading"
        :data-level="String(block.level)"
      >
        <RichTextContentInlines :inlines="block.inlines" />
      </h2>
      <!-- list -->
      <ol
        v-else-if="block.kind === 'list' && block.ordered"
        :class="styles.list"
        :start="block.start"
      >
        <template v-for="(entry, position) in block.items" :key="position">
          <RichTextContentItem :blocks="entry" />
        </template>
      </ol>
      <!-- list -->
      <ul v-else-if="block.kind === 'list'" :class="styles.list">
        <template v-for="(entry, position) in block.items" :key="position">
          <RichTextContentItem :blocks="entry" />
        </template>
      </ul>
      <!-- quote -->
      <blockquote v-else-if="block.kind === 'quote'" :class="styles.quote">
        <RichTextContentBlocks :blocks="block.blocks" />
      </blockquote>
      <CodeBlock
        v-else-if="block.kind === 'codeBlock' && block.at === null"
        :copyable="block.copyable"
        :label="block.language"
      >
        {{ block.text }}
      </CodeBlock>
      <div
        v-else-if="block.kind === 'codeBlock'"
        v-bind="richTextPositionAttrs(block.at, true, true)"
      >
        <CodeBlock :copyable="block.copyable" :label="block.language">
          {{ block.text }}
        </CodeBlock>
      </div>
      <Text v-else-if="block.kind === 'later' && block.at === null" :size="owner.size">
        {{ block.text }}
      </Text>
      <Text v-else-if="block.kind === 'later'" :size="owner.size">
        <span v-bind="richTextPositionAttrs(block.at, true)">
          {{ block.text }}
        </span>
      </Text>
    </template>
  </li>
</template>
